ALTER TABLE furniture_templates ADD COLUMN category text NOT NULL DEFAULT 'other' CHECK(category IN ('desk','chair','cabinet','pedestal','sofa','meeting_table','storage','sanitary','equipment','other'));
ALTER TABLE furniture_templates ADD COLUMN real_width_m double precision CHECK(real_width_m>0 AND real_width_m<=100);
ALTER TABLE furniture_templates ADD COLUMN real_depth_m double precision CHECK(real_depth_m>0 AND real_depth_m<=100);
ALTER TABLE furniture_templates ADD COLUMN resize_allowed boolean NOT NULL DEFAULT true;
ALTER TABLE furniture_templates ADD COLUMN default_properties jsonb NOT NULL DEFAULT '{}';
CREATE TABLE floor_calibrations(id text PRIMARY KEY,floor_id text NOT NULL REFERENCES floors,points jsonb NOT NULL,real_distance_m numeric NOT NULL CHECK(real_distance_m>0),meters_per_unit double precision NOT NULL CHECK(meters_per_unit>0),source text NOT NULL,confidence text NOT NULL CHECK(confidence='measured'),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenants(id text PRIMARY KEY,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('internal','external')),company_reference text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lease_agreements(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants,contract_number text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,status text NOT NULL CHECK(status IN ('active','cancelled')),currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),common_model text NOT NULL CHECK(common_model IN ('none','selected','proportional','manual')),allocation_snapshot jsonb NOT NULL,comment text NOT NULL DEFAULT '',created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(end_date>start_date),UNIQUE(tenant_id,contract_number));
CREATE TABLE lease_lines(id text PRIMARY KEY,lease_id text NOT NULL REFERENCES lease_agreements,room_id text REFERENCES rooms,floor_id text NOT NULL REFERENCES floors,label text NOT NULL,kind text NOT NULL CHECK(kind IN ('office','common')),space_type_id text REFERENCES space_types,area_m2 numeric NOT NULL CHECK(area_m2>0),rate numeric NOT NULL CHECK(rate>=0),unit text NOT NULL DEFAULT 'm2_month' CHECK(unit='m2_month'),valid_from date NOT NULL,valid_to date NOT NULL,CHECK(valid_to>valid_from));
CREATE INDEX lease_lines_room_window ON lease_lines(room_id,valid_from,valid_to);
CREATE INDEX lease_lines_agreement_window ON lease_lines(lease_id,valid_from,valid_to);
CREATE INDEX lease_expiry ON lease_agreements(end_date) WHERE status='active';
CREATE TABLE workflow_previews(id text PRIMARY KEY,kind text NOT NULL,actor_id text NOT NULL,payload jsonb NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),applied_at timestamptz);
